  const [prevName, setPrevName] = useState(name);
  const inputRef = useRef<HTMLInputElement>(null);

  if (name !== prevName) {
    setPrevName(name);
    setDraftName(name);
  }

  useEffect(() => {
    if (isEditing) {
      inputRef.current?.focus();
      inputRef.current?.select();
    }
  }, [isEditing]);

  const handleDoubleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!locked && onRename) {
      setIsEditing(true);
