  waiting: number;
  losses: number;
  restores: number;
};

type Win = {
  __LL_TEST__?: boolean;
  __LL_COMMANDS__?: {
    all: () => Array<{ id: string; run: (args?: unknown) => unknown }>;
    context: () => Record<string, unknown>;
  };
  __LL_COMPOSITOR__?: {
    stats: () => Stats;
    loseShared: () => void;
    restoreShared: () => void;
  };
};

async function readyEditor(page: Page) {
  await page.addInitScript(() => {
    (window as unknown as Win).__LL_TEST__ = true;
  });
